SELECT * 
FROM meal
WHERE user_id = #{userId}
  AND meal_date = #{mealDate}

SELECT DISTINCT
	meal_date AS mealDate
FROM meal
WHERE user_id = #{userId}
AND YEAR(meal_date) = #{year}
AND MONTH(meal_date) = #{month}
AND is_recommendation = 0

SELECT *
FROM meal
WHERE user_id = #{userId}
AND meal_date
BETWEEN #{startDate} AND #{endDate}
